// =============================================================================
// /robots.txt — generated by Next.js.
// =============================================================================
// Public marketing pages are fully crawlable AND explicitly welcome to AI
// answer engines (we want to be cited in LLM answers). App/admin/API surfaces
// are blocked from indexing. Low-value SEO scrapers that hammer origins are
// blocked entirely. The /mcp WebMCP endpoint is a top-level route (not under
// /api/), so it stays reachable by agents while crawlers skip /api/.
// =============================================================================

import type { MetadataRoute } from 'next';

const PRIVATE = ['/dashboard/', '/platform/', '/onboarding', '/login', '/signup', '/api/'];

const AI_BOTS = [
  'GPTBot',
  'ChatGPT-User',
  'OAI-SearchBot',
  'ClaudeBot',
  'Claude-Web',
  'Claude-SearchBot',
  'anthropic-ai',
  'PerplexityBot',
  'Perplexity-User',
  'Google-Extended',
  'Applebot-Extended',
  'Amazonbot',
  'CCBot',
  'Bytespider',
  'DuckAssistBot',
  'YouBot',
  'MistralAI-User',
  'Meta-ExternalAgent',
  'cohere-ai',
  'Diffbot',
];

export default function robots(): MetadataRoute.Robots {
  const base = (process.env.NEXT_PUBLIC_APP_URL ?? 'https://topbuilderai.com').replace(/\/$/, '');
  return {
    rules: [
      { userAgent: '*', allow: '/', disallow: PRIVATE },
      ...AI_BOTS.map((ua) => ({ userAgent: ua, allow: '/', disallow: ['/dashboard/', '/platform/', '/api/'] })),
      { userAgent: ['SemrushBot', 'AhrefsBot', 'MJ12bot', 'DotBot', 'PetalBot'], disallow: '/' },
    ],
    sitemap: `${base}/sitemap.xml`,
    host: base,
  };
}
